function targetDivision($b){$id=$b['division_id']??null;if(!$id&&(!empty($b['year'])||!empty($b['year_level']))&&!empty($b['division'])){$d=strtoupper(trim(preg_replace('/Division\s*/i','',$b['division'])));$r=one('SELECT id FROM class_divisions WHERE year_level=? AND division=? LIMIT 1',[strtoupper($b['year']??$b['year_level']),$d]);$id=$r['id']??null;}return $id;}
