 $recs=rows('SELECT ar.*,sess.session_date,sess.lecture_slot,sess.room_no,sub.name subject_name,sub.code subject_code,u.full_name marked_by_name FROM attendance_records ar JOIN attendance_sessions sess ON sess.id=ar.session_id JOIN subjects sub ON sub.id=sess.subject_id LEFT JOIN users u ON u.id=ar.marked_by_user_id WHERE ar.student_id=? ORDER BY sess.session_date DESC,sess.lecture_slot DESC',[$st['id']]);$recordDates=[];foreach($recs as $r)$recordDates[$r['session_date']][]=$r;
 $month=$q['month']??gmdate('Y-m');if(!preg_match('/^(\d{4})-(0[1-9]|1[0-2])$/',$month,$mm))fail('Month must be YYYY-MM.');$days=[];$daysIn=(int)date('t',strtotime($month.'-01'));for($day=1;$day<=$daysIn;$day++){$date=$month.'-'.str_pad($day,2,'0',STR_PAD_LEFT);$dow=(int)date('w',strtotime($date));$h=$holidays[$date]??null;$ds=$byDate[$date]??[];$dr=$recordDates[$date]??[];$present=count(array_filter($dr,fn($r)=>in_array($r['status'],['PRESENT','LATE'])));$total=count($ds);$status=$h&&(int)$h['is_instructional_day']===0?'HOLIDAY':($total===0?($dow===0?'HOLIDAY':'NO_LECTURE'):($present===$total?'PRESENT':($present===0?'ABSENT':'PARTIAL')));$days[]=['date'=>$date,'day'=>$day,'dayOfWeek'=>$dow,'status'=>$status,'is_holiday'=>$status==='HOLIDAY','holiday_name'=>$h['title']??($dow===0?'Sunday Weekend':null),'is_modified'=>count(array_filter($dr,fn($r)=>!empty($r['modified_by'])||$r['attendance_method']==='Manual Edit'))>0,'total_sessions'=>$total,'present_sessions'=>$present];}
